// Standalone real-kernel adoption gate; accepts an owned candidate via --wasm.
import fs from 'node:fs';
import assert from 'node:assert/strict';
import test from 'node:test';
const wasm=process.argv[2]==='--wasm'?process.argv[3]:'handoff/flight/flight_core.wasm';
const module=await WebAssembly.compile(fs.readFileSync(wasm));
const profile=JSON.parse(fs.readFileSync('data/aircraft/frontline.json')).aircraft.me262.physics;
async function make(){const api=(await WebAssembly.instantiate(module,{math:{sin:Math.sin,cos:Math.cos,atan2:Math.atan2,exp:Math.exp,asin:Math.asin,acos:Math.acos},world:{ground:()=>0,landable:()=>1}})).exports;api.set_world(1);api.configure_airframe(...profile.airframe);api.configure_surfaces(...profile.surfaces);api.configure_gear_sequence(...profile.gearSequence);api.configure(...profile.configure);api.configure_control(...profile.control);api.configure_envelope(...profile.envelope);api.spawn(0,2000,0,0,160,0);return{api,s:new Float32Array(api.memory.buffer,api.state_ptr(),80),a:new Float32Array(api.memory.buffer,api.aero_state_ptr(),48)};}
test('kinematic adoption changes real next-step plant state while preserving engine/time/gear/damage',async()=>{
 const {api,s,a}=await make();assert.equal(typeof api.adopt_kinematics,'function','actual shared flight core needs scoped adoption');api.set_damage(0,1,1,.5,.6,.7);api.set_gear_failure(1);api.step(1/120,0,0,1,.8,0,0,0,133);const before={time:s[23],engine:s[27],gear:s[33],axes:Array.from(a.slice(36,40))};
 assert.equal(api.adopt_kinematics(10,2100,20,0,0,0,1,5,1,150,.1,.2,.3),1);assert.equal(s[0],10);assert.equal(s[1],2100);assert.equal(s[2],20);assert.equal(s[23],before.time);assert.equal(s[27],before.engine);assert.equal(s[33],before.gear);assert.deepEqual(Array.from(a.slice(36,40)),before.axes);
 api.step(1/120,0,0,1,.8,0,0,0,133);assert.ok(s[0]>10);assert.equal(s[37],0,'accepted engine damage remains applied');assert.equal(s[33],0,'accepted gear failure remains irreversible');
});
test('invalid transforms are rejected atomically',async()=>{const {api,s}=await make();assert.equal(typeof api.adopt_kinematics,'function');for(const bad of [[NaN,2000,0,0,0,0,1,0,0,160,0,0,0],[0,2000,0,0,0,0,0,0,0,160,0,0,0],[0,-10,0,0,0,0,1,0,0,160,0,0,0],[0,2000,0,0,0,0,1,0,0,10000,0,0,0]]){const before=Float32Array.from(s);assert.equal(api.adopt_kinematics(...bad),0);assert.deepEqual(s,before);}});
test('adoption cannot revive a kernel-authoritative crash',async()=>{const {api,s}=await make();assert.equal(typeof api.adopt_kinematics,'function');api.spawn(0,2,0,0,0,0);api.step(1/120,0,0,1,0,0,0,0,0);assert.equal(s[22],1);assert.equal(api.adopt_kinematics(0,2000,0,0,0,0,1,0,0,160,0,0,0),0);assert.equal(s[22],1);});
test('initial control seeding retains accepted engine and mid-gear axes without allowing a running reset',async()=>{const {api,s,a}=await make();assert.equal(typeof api.seed_control_state,'function','handoff must retain actual engine and actuator state');assert.equal(api.seed_control_state(.91,.2,-.3,.1,.6,.25,.5,1,1,.2,1),1);assert.ok(Math.abs(s[27]-.91)<1e-6);assert.ok(Math.abs(s[24]-.2)<1e-6);assert.ok(Math.abs(s[33]-.6)<1e-6);assert.ok(Math.abs(a[38]-.2)<1e-6);api.step(1/120,0,0,1,.91,0,0,0,133);const gear=s[33];assert.equal(api.seed_control_state(.91,0,0,0,1,.5,0,1,1,1,1),0);assert.equal(s[33],gear);api.spawn(0,2000,0,0,160,0);api.set_gear_failure(1);assert.equal(api.seed_control_state(.91,0,0,0,1,.5,0,1,1,1,1),0);assert.equal(s[33],0);});
